svg.script:
(function(){
  var TOTAL=5000, X0=400, W=800;
  var stat=document.getElementById("stat"), pct=document.getElementById("pct"),
      fill=document.getElementById("fill"), head=document.getElementById("headg"),
      m=document.getElementById("m");
  var steps=[[0,"Powering up engines"],[14,"Charting the stars"],[32,"Aligning orbits"],[52,"Warming the nebula"],[72,"Calibrating thrusters"],[90,"Preparing for launch"],[99,"Ready"]];
  var data=null,failed=false,t0=performance.now();
  var src=new URL("SpacePad.html",location.href).href;
  fetch(src,{cache:"no-cache"}).then(function(r){
    if(!r.ok)throw new Error("HTTP "+r.status);
    return r.arrayBuffer();
  }).then(function(buf){data=buf;}).catch(function(e){failed=true;m.textContent="Could not load SpacePad.html: "+e.message;m.setAttribute("fill","#ff9aa8");});
  function ease(t){return t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;}
  function go(){
    var url=URL.createObjectURL(new Blob([data],{type:"text/html;charset=utf-8"}));
    location.replace(url);
  }
  function frame(now){
    if(failed)return;
    var t=Math.min(1,(now-t0)/TOTAL);
    var p=ease(t)*100;
    if(!data&&p>99)p=99; /* hold at 99 until the file has arrived */
    var w=W*p/100;
    fill.setAttribute("width",w.toFixed(1));
    head.setAttribute("transform","translate("+(X0+w).toFixed(1)+" 647)");
    pct.textContent=Math.floor(p)+"%";
    for(var i=steps.length-1;i>=0;i--){if(p>=steps[i][0]){stat.textContent=steps[i][1]+"...";break;}}
    if(t>=1&&data){pct.textContent="100%";fill.setAttribute("width",W);setTimeout(go,250);return;}
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
